/* ================= t373 (butchkill.js) the kill (owner: "Butchering should include you having to put down the animal also with blood cruelty all
   that"). Done yourself, the butcher's block starts with the animal alive. The hen: you pin her to the block with your hand while she
   kicks, then take her head off with the hatchet. A clean blow takes it in one: the neck spurts, the body flaps and kicks on the block,
   the beak opens and shuts. A bad blow only cuts her, and she shrieks and thrashes and you strike again. The cow: roped to the post,
   eyes rolling white, she won't keep her head still; you stun her with the sledge, and a glancing blow makes her bellow and bleed
   from the brow and you swing again. Then her throat, and she bleeds out in pulses into the bucket until it runs over, her legs
   kicking slower, and she is hoisted for the cutting. Every extra blow costs a little quality. The blood stays on the block, the
   wall and your hand for the rest of the scene. Toned down: the same steps; at each strike the frame cuts to the barn wall, the
   sound plays, and there's a short dark smear after: no spurts, kicking or severed head. ================= */
const BK={after:{}};
BK.full=()=>!window.GORE_TONED;
// ---------------------------------------------------------------- the sounds (the game's own synth)
BK.snd={
  shriek(k){k=k||1;A.tone(MSV(1500,.1),.34*k,'sawtooth',.05,{slide:2300,filter:['bandpass',1800,3]});A.tone(MSV(2100,.1),.28*k,'square',.022,{slide:1500,delay:.06,filter:['bandpass',2200,4]});A.hiss(.24*k,.05,'bandpass',2600,{q:3,wobble:1});},
  squawk(){A.tone(MSV(900,.15),.12,'sawtooth',.04,{slide:1300,filter:['bandpass',1400,2]});A.tone(MSV(700),.08,'square',.02,{slide:500,delay:.1,filter:['bandpass',1200,2]});},
  flap(){for(let i=0;i<2;i++)A.hiss(.07,.07,'bandpass',MSV(900,.3),{q:.8,delay:i*.07});},
  bawl(k){k=k||1;A.tone(MSV(150,.08),1.05*k,'sawtooth',.08,{slide:112,a:.12,filter:['lowpass',700,2]});A.tone(MSV(300,.08),.95*k,'sawtooth',.026,{slide:226,a:.15,filter:['bandpass',900,5]});A.hiss(.8*k,.025,'bandpass',600,{q:2,a:.1});},
  bellow(){A.tone(220,1.3,'sawtooth',.11,{slide:118,a:.04,filter:['lowpass',900,3]});A.tone(440,1.2,'sawtooth',.035,{slide:250,filter:['bandpass',1100,6]});A.hiss(1.1,.07,'bandpass',800,{q:2,wobble:1});},
  thud(k){k=k||1;A.tone(85,.32,'sine',.42*k,{slide:38});A.hiss(.12,.3*k,'lowpass',520,{slide:150});A.hiss(.03,.14*k,'bandpass',1400,{q:1});},
  chop(){MS.cleave&&MS.cleave();A.hiss(.03,.3,'bandpass',2400,{q:1.2});A.tone(150,.12,'sine',.28,{slide:70,delay:.01});for(let i=0;i<3;i++)A.hiss(.025,.12,'bandpass',MSV(1500,.4),{q:2,delay:.02+i*.018});},
  pulse(k){k=k||1;A.hiss(.34,.12*k,'lowpass',MSV(520,.2),{slide:220,wobble:1});A.tone(MSV(110,.2),.24,'sine',.06*k,{slide:68,delay:.04});for(let i=0;i<3;i++)A.tone(MSV(240,.4),.05,'sine',.03*k,{slide:110,delay:.1+i*.06});},
  drop(){A.tone(70,.5,'sine',.45,{slide:32});A.hiss(.4,.25,'lowpass',400,{slide:120});A.hiss(.6,.06,'bandpass',300,{q:1,delay:.1,wobble:1});}};
// ---------------------------------------------------------------- the pieces drawn for it
// the barn wall the frame cuts to (toned down)
BK.wall=()=>M4.pre('bk_wall1',320,180,k=>{k.planks(0,0,320,180,CA_P.wood,18,7,true);for(let y=0;y<180;y+=2)for(let x=0;x<320;x+=2){const d=Math.hypot((x-160)/180,(y-80)/115);if(d>.72)k.pa(x,y,2,2,'#08040a',Math.min(.7,Math.round((d-.72)*6)/6));}});
// a short dark smear (toned down): one low cluster
BK.smear=(K,x,y)=>{const P=BG71.BLT;x=Math.round(x);y=Math.round(y);K.px(x-3,y,7,2,P[2]);K.px(x-2,y-1,4,1,P[3]);K.px(x-4,y+1,2,1,P[1]);K.px(x+3,y+1,3,1,P[1]);K.px(x,y+2,3,1,P[1]);};
