BK.hatchet=bl=>M4.pre('bk_hatchet2_'+(bl||0),48,22,(K)=>{const I=CA_P.iron,Wd=CA_P.wood,B=BG71.BL;
  for(let x=13;x<46;x++){const th=x>40?5:4,y0=x>40?8:9;for(let y=0;y<th;y++)K.px(x,y0+y,1,1,Wd[y===0?6:y===th-1?2:4]);}K.px(45,8,1,5,Wd[1]);
  for(let y=3;y<=21;y++){const l=y<11?9:Math.max(0,Math.round(9-(y-11)*.95)),r=16;for(let x=l;x<=r;x++){let k=y<6?6:x<l+2&&y>12?7:x>13?3:5;if(y>=20)k=7;if(x===r)k=2;K.px(x,y,1,1,I[k]);}}
  K.px(9,3,8,1,I[7]);K.px(15,8,2,6,I[2]);for(let y=12;y<=21;y++){const l=Math.max(0,Math.round(9-(y-11)*.95));K.px(l,y,1,1,'#f4f6f8');}
  // blood up the blade from its edge, gathered, a run toward the eye
  if(bl)for(let y=12;y<=21;y++){const l=Math.max(0,Math.round(9-(y-11)*.95)),w=Math.min(9,2+(y-12)*(bl>1?1:.6));for(let x=l;x<l+w&&x<16;x++)K.px(x,y,1,1,x===l?B[4]:x<l+2?B[3]:B[2]);if(bl>1&&y===16)K.px(l+3,y,1,1,B[5]);}
  if(bl>1){K.px(12,8,2,4,B[3]);K.px(12,8,1,1,B[4]);}},true);
// the sledge: an iron block on a long handle; it strikes with its underside
BK.sledge=()=>M4.pre('bk_sledge1',84,16,(K)=>{const I=CA_P.iron,Wd=CA_P.oak;
  for(let x=17;x<83;x++){const y0=x>72?5:6,th=x>72?5:4;for(let y=0;y<th;y++)K.px(x,y0+y,1,1,Wd[y===0?6:y===th-1?2:4]);}
  for(let y=0;y<15;y++)for(let x=0;x<18;x++){let k=y<2?7:y>12?6:x<3?5:x>14?2:4;if((x===0||x===17)&&(y===0||y===14))continue;K.px(x,y,1,1,I[k]);}K.px(1,14,16,1,I[7]);K.px(17,4,2,8,I[1]);},true);
