  rows.forEach(([l,r],i)=>{const y=27+i;for(let x=l;x<=r;x++){let c=x===l?Rw[0]:x===l+1?Rw[1]:(x+i*2)%7===0?Rw[1]:i<4&&x<l+4?Rw[4]:Rw[3];if(x===r)c=i%3===1?W[3]:B[3];K.px(x,y,1,1,c);}});
