BK.img=n=>{const d=BK.IMG[n];return M4.pre('bkimg_'+n,d[0],d[1],(K,g)=>{const id=g.createImageData(d[0],d[1]),a=id.data,rgb=d[2].split(',').map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)));let i=0;d[3].replace(/([^0-9])([0-9]*)/g,(m,c,n)=>{const k=n?+n:1;if(c!=='.'){const p=rgb[BK.AL.indexOf(c)];for(let q=0;q<k;q++){const o=(i+q)*4;a[o]=p[0];a[o+1]=p[1];a[o+2]=p[2];a[o+3]=255;}}i+=k;return '';});g.putImageData(id,0,0);});};
