// a glancing cut through the neck feathers: a slanted tear, dark in its depth, a raw lip lit above it, the feathers parted round it
BK.glance=(K,X,Y,P,full)=>{const M=BT3.MEAT,W=BG71.WHT;X=Math.round(X);Y=Math.round(Y);
  for(let i=-7;i<=6;i++){const x=X+i,y=Y+Math.round(i*.45),e=i===-7||i===6,m=Math.abs(i)<4;K.px(x,y-1,1,1,e?W[2]:full?M[5]:P[2]);K.px(x,y,1,1,e?P[1]:P[0]);if(!e)K.px(x,y+1,1,1,full?(m?P[3]:M[2]):P[1]);if(m&&full)K.px(x,y+2,1,1,P[2]);}
  K.px(X-4,Y-5,5,1,W[5]);K.px(X-5,Y-4,2,1,W[4]);K.px(X+2,Y-3,4,1,W[5]);K.px(X-8,Y-2,2,1,W[2]);K.px(X+5,Y+5,2,1,W[2]);};
// a run spilling down a surface from a lip: thin where it leaves, thickening as it goes, a bead at its foot
BK.spill=(K,x,y,len,t0,t,sp,P)=>{const n=Math.min(len,Math.floor(Math.max(0,t-t0)*sp));if(n<1)return;K.px(x-1,y-1,3,2,P[3]);K.px(x-1,y-1,1,1,P[4]);
  for(let i=0;i<n;i++){const w=1+Math.floor(i/len*3);K.px(x,y+1+i,w,1,P[3]);if(w>1){K.px(x,y+1+i,1,1,P[4]);K.px(x+w,y+1+i,1,1,P[1]);}}
  if(n>2){const w=1+Math.floor(n/len*3);K.px(x,y+1+n,w+1,2,P[3]);K.px(x+w,y+2+n,1,1,P[1]);K.px(x,y+1+n,1,1,P[5]);}};
// blood gathering on the hatchet's edge, hanging, and letting go: one drop at a time falls to the block, where it gathers
BK.drip=(K,px,py,ang,d,P)=>{let ex=0,ey=-1e9;const c=Math.cos(ang),s=Math.sin(ang);for(let y=12;y<=21;y++){const x=Math.max(0,Math.round(9-(y-11)*.95)),X=px+(36-x)*c-(y-10)*s,Y=py+(36-x)*s+(y-10)*c;if(Y>ey){ey=Y;ex=X;}}
  ex=Math.round(ex);ey=Math.round(ey);const per=.8,p=(d%per)/per,n=Math.floor(d/per),land=ey+22;
  if(n>0){const r=Math.min(3,n);K.px(ex-r+1,land,r*2,1,P[3]);K.px(ex-r+2,land+1,r*2-2,1,P[1]);K.px(ex-r+1,land,1,1,P[4]);}
  if(p<.65){const h=1+Math.round(p/.65*3);K.px(ex,ey+1,1,h,P[3]);K.px(ex,ey+h,2,2,P[3]);K.px(ex,ey+h,1,1,P[5]);}
  else{const q=(p-.65)/.35,y=Math.round(ey+3+q*q*(land-ey-3));if(y<land-1){K.px(ex,y,2,3,P[3]);K.px(ex,y,1,1,P[5]);K.px(ex,ey+1,1,1,P[3]);}}};
